-- Schema of database 'hh_sanitation' (PostgreSQL 16), generated by Hibernate from the JPA entities.
-- Reference only: the services create/update these tables automatically (spring.jpa.hibernate.ddl-auto=update).

CREATE TABLE public.maintenance_tasks (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    actual_cost double precision,
    assigned_to character varying(255),
    completed_date date,
    completion_notes character varying(1000),
    description character varying(1000) NOT NULL,
    estimated_cost double precision,
    facility_id bigint NOT NULL,
    facility_name character varying(255),
    maintenance_type character varying(20) NOT NULL,
    priority character varying(10),
    reported_by character varying(255),
    scheduled_date date,
    source character varying(15),
    status character varying(15),
    task_number character varying(20),
    village character varying(255),
    CONSTRAINT maintenance_tasks_maintenance_type_check CHECK (((maintenance_type)::text = ANY ((ARRAY['CLEANING'::character varying, 'REPAIR'::character varying, 'PLUMBING'::character varying, 'ELECTRICAL'::character varying, 'PEST_CONTROL'::character varying, 'DESLUDGING'::character varying, 'DRAIN_DESILTING'::character varying, 'PAINTING'::character varying, 'CONSTRUCTION'::character varying])::text[]))),
    CONSTRAINT maintenance_tasks_priority_check CHECK (((priority)::text = ANY ((ARRAY['LOW'::character varying, 'MEDIUM'::character varying, 'HIGH'::character varying, 'CRITICAL'::character varying])::text[]))),
    CONSTRAINT maintenance_tasks_source_check CHECK (((source)::text = ANY ((ARRAY['MANUAL'::character varying, 'COMPLAINT'::character varying, 'INSPECTION'::character varying, 'FIELD_REPORT'::character varying, 'SCHEDULED'::character varying])::text[]))),
    CONSTRAINT maintenance_tasks_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'ASSIGNED'::character varying, 'IN_PROGRESS'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying])::text[])))
);
ALTER TABLE public.maintenance_tasks ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.maintenance_tasks_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.sanitation_complaints (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    assigned_to character varying(255),
    category character varying(25) NOT NULL,
    channel character varying(255),
    complainant_name character varying(255),
    complainant_phone character varying(255),
    complaint_number character varying(20),
    description character varying(1000) NOT NULL,
    facility_id bigint,
    facility_name character varying(255),
    maintenance_task_id bigint,
    priority character varying(10),
    reported_date date,
    resolution_notes character varying(1000),
    resolved_date date,
    status character varying(15),
    village character varying(255) NOT NULL,
    CONSTRAINT sanitation_complaints_category_check CHECK (((category)::text = ANY ((ARRAY['UNCLEAN_TOILET'::character varying, 'BLOCKED_DRAIN'::character varying, 'NO_WATER'::character varying, 'BROKEN_FIXTURE'::character varying, 'SEWAGE_OVERFLOW'::character varying, 'GARBAGE_NOT_COLLECTED'::character varying, 'OPEN_DEFECATION'::character varying, 'BAD_ODOUR'::character varying, 'NO_LIGHTING'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT sanitation_complaints_priority_check CHECK (((priority)::text = ANY ((ARRAY['LOW'::character varying, 'MEDIUM'::character varying, 'HIGH'::character varying, 'CRITICAL'::character varying])::text[]))),
    CONSTRAINT sanitation_complaints_status_check CHECK (((status)::text = ANY ((ARRAY['OPEN'::character varying, 'IN_PROGRESS'::character varying, 'RESOLVED'::character varying, 'CLOSED'::character varying, 'REJECTED'::character varying])::text[])))
);
ALTER TABLE public.sanitation_complaints ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.sanitation_complaints_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.sanitation_facilities (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    accessible_for_disabled boolean,
    capacity integer,
    caretaker_name character varying(255),
    caretaker_phone character varying(255),
    cleanliness_status character varying(15),
    electricity_available boolean,
    facility_code character varying(20),
    gender_separated boolean,
    landmark character varying(255),
    last_cleaned_date date,
    last_inspection_date date,
    latitude double precision,
    longitude double precision,
    managed_by character varying(255),
    name character varying(255) NOT NULL,
    status character varying(20),
    type character varying(25) NOT NULL,
    village character varying(255) NOT NULL,
    ward character varying(255),
    water_available boolean,
    CONSTRAINT sanitation_facilities_cleanliness_status_check CHECK (((cleanliness_status)::text = ANY ((ARRAY['CLEAN'::character varying, 'SATISFACTORY'::character varying, 'DIRTY'::character varying, 'UNUSABLE'::character varying])::text[]))),
    CONSTRAINT sanitation_facilities_status_check CHECK (((status)::text = ANY ((ARRAY['OPERATIONAL'::character varying, 'UNDER_MAINTENANCE'::character varying, 'NON_FUNCTIONAL'::character varying])::text[]))),
    CONSTRAINT sanitation_facilities_type_check CHECK (((type)::text = ANY ((ARRAY['COMMUNITY_TOILET'::character varying, 'PUBLIC_TOILET'::character varying, 'SCHOOL_TOILET'::character varying, 'DRAINAGE'::character varying, 'WASTE_COLLECTION_POINT'::character varying, 'SOAK_PIT'::character varying, 'HANDWASH_STATION'::character varying, 'FAECAL_SLUDGE_PLANT'::character varying, 'COMPOST_PIT'::character varying])::text[])))
);
ALTER TABLE public.sanitation_facilities ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.sanitation_facilities_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.sanitation_inspections (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    cleanliness_status character varying(15) NOT NULL,
    facility_id bigint NOT NULL,
    facility_name character varying(255),
    inspection_date date,
    inspector_name character varying(255),
    lighting_working boolean,
    maintenance_task_id bigint,
    odour_free boolean,
    rating integer NOT NULL,
    remarks character varying(1000),
    soap_available boolean,
    village character varying(255),
    water_available boolean,
    CONSTRAINT sanitation_inspections_cleanliness_status_check CHECK (((cleanliness_status)::text = ANY ((ARRAY['CLEAN'::character varying, 'SATISFACTORY'::character varying, 'DIRTY'::character varying, 'UNUSABLE'::character varying])::text[]))),
    CONSTRAINT sanitation_inspections_rating_check CHECK (((rating <= 5) AND (rating >= 1)))
);
ALTER TABLE public.sanitation_inspections ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.sanitation_inspections_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
